head.script:
scwin.select1_onlabelclick = function(index, checked, value) {
    log = true;
    //alert('label');
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. IE11에서 샘플파일을 실행 후 텍스트 부분을 클릭한다(checkBox 체크 하면 안됨)
    //1. Run the sample file in IE11 and click on the text field (checkBox should not be checked)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2checkbox_label ')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 알림창에 'label'이 보여진다.(정상) (이전에는 알림창이 뜨지않음)
    //1. 'label' is displayed in the notification window (normal) (Previously no notification window)
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = false;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
